(function(){
 let ctx=null;
 function ac(){if(!ctx){try{ctx=new (window.AudioContext||window.webkitAudioContext)()}catch(e){return null}}if(ctx&&ctx.state==='suspended')ctx.resume();return ctx}
 function tone(freq,t0,dur,type,vol,slideTo){
  const c=ac();if(!c)return;
  const o=c.createOscillator(),g=c.createGain();
  o.type=type||'sine';o.frequency.setValueAtTime(freq,t0);
  if(slideTo)o.frequency.exponentialRampToValueAtTime(slideTo,t0+dur);
  g.gain.setValueAtTime(0.0001,t0);
  g.gain.exponentialRampToValueAtTime(vol||.16,t0+.012);
  g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  o.connect(g);g.connect(c.destination);o.start(t0);o.stop(t0+dur+.03);
 }
 function noiseBurst(t0,dur,vol,hp){
  const c=ac();if(!c)return;
  const n=Math.floor(c.sampleRate*dur),buf=c.createBuffer(1,n,c.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);
  const s=c.createBufferSource();s.buffer=buf;
  const g=c.createGain();g.gain.setValueAtTime(vol,t0);g.gain.exponentialRampToValueAtTime(.0001,t0+dur);
  const f=c.createBiquadFilter();f.type='highpass';f.frequency.value=hp||1400;
  s.connect(f);f.connect(g);g.connect(c.destination);s.start(t0);
 }
 const vibrate=p=>{try{if(navigator.vibrate)navigator.vibrate(p)}catch(e){}};
 const SFX={
  tap(){const c=ac();if(c)tone(540,c.currentTime,.07,'sine',.06)},
  correct(){const c=ac();if(c){const t=c.currentTime;tone(660,t,.12,'sine',.15);tone(880,t+.09,.18,'sine',.15)}vibrate(12)},
  wrong(){const c=ac();if(c){const t=c.currentTime;tone(240,t,.16,'triangle',.11,170)}vibrate(35)},
  hatch(){const c=ac();if(c){const t=c.currentTime;noiseBurst(t,.12,.16,1500);tone(523,t+.08,.12,'sine',.13);tone(659,t+.17,.12,'sine',.13);tone(784,t+.26,.2,'sine',.13)}vibrate([25,40,25])},
  win(){const c=ac();if(c){const t=c.currentTime;[523,659,784,1047].forEach((f,i)=>tone(f,t+i*.11,.22,'sine',.14))}vibrate([30,50,30])},
  lose(){const c=ac();if(c){const t=c.currentTime;tone(330,t,.18,'triangle',.09);tone(262,t+.14,.26,'triangle',.09)}}
 };
 const wrap=function(name,fn){const orig=window[name];if(typeof orig==='function'){window[name]=function(){const r=orig.apply(this,arguments);try{fn.apply(this,arguments)}catch(e){}return r}}};
 wrap('finishQuestion',function(ok){ok?SFX.correct():SFX.wrong()});
 wrap('finishCard',function(){SFX.hatch()});
 wrap('showResult',function(){
  let rate=0;try{const s=window.__quizStats?window.__quizStats():null;if(s&&s.total)rate=Math.round(s.correct/s.total*100)}catch(e){}
  rate>=70?SFX.win():SFX.lose();
 });
 document.addEventListener('click',function(e){
  if(!e.target||!e.target.closest)return;
  if(e.target.closest('.option,.judge-btn,#orderCheck'))return;
  if(e.target.closest('.theme-card,.mode-card,.lesson-card,.vocab-item,.swap-chip,.pat-card,.mini-spk,.speak-btn,.big-listen,.order-token,.back-btn,.big-btn,.result-btn'))SFX.tap();
 });
 window.__SFX=SFX;
})();
