(function(){
  function ready(fn){ if(document.readyState!=='loading') fn(); else document.addEventListener('DOMContentLoaded',fn); }

  /* 自绘描边扁平图标（currentColor，零版权） */
  var ICON_MARK='<svg class="pq-cover-mark" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="24" cy="24" r="21" stroke-dasharray="3 3.5"/><path d="M6 28 L42 13 L33 38 L27 30 L20 34 L19 27 Z" fill="currentColor" stroke="none"/></svg>';

  /* 1. 封面品牌：移除卡通云朵/太阳/蛋，改为杂志刊头 */
  function buildCover(){
    var hero=document.querySelector('#homePage .hero'); if(!hero) return;
    hero.querySelectorAll('.hero-cloud,.plane-trail,.hero-egg').forEach(function(n){n.remove();});
    var h1=hero.querySelector('h1');
    if(h1){
      h1.innerHTML='<div class="pq-cover-head"><div>'+
        '<div class="pq-kicker">Revista de Viaje</div>'+
        '<div class="pq-brand-es">Paquete de Viaje</div>'+
        '<div class="pq-brand-cn">旅 行 刊</div>'+
        '</div></div>';
    }
    var p=hero.querySelector('p');
    if(p){ p.textContent='阿蛋西语 · 西语游学杂志'; }
  }

  /* 1b. 锁屏品牌化：蓝色卡通飞机蛋 → 扁平描边邮戳 */
  function buildLock(){
    var logo=document.querySelector('#lockScreen .lock-logo');
    if(logo){
      logo.outerHTML='<svg class="lock-logo" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" style="color:var(--terracotta)"><circle cx="24" cy="24" r="21" stroke-dasharray="3 3.5"/><path d="M6 28 L42 13 L33 38 L27 30 L20 34 L19 27 Z" fill="currentColor" stroke="none"/></svg>';
    }
    var lh=document.querySelector('#lockScreen .lock-card h1');
    if(lh){ lh.textContent='Paquete de Viaje'; }
    var sub=document.querySelector('#lockScreen .lock-sub');
    if(sub){ sub.innerHTML='旅行刊 · 阿蛋西语游学杂志<br>输入访问密码，开启西语之旅'; }
    var btn=document.getElementById('lockBtn');
    if(btn){ btn.textContent='✈️ 出 发'; }
  }

  /* 2. 栏目西语小标 */
  function refineSections(root){
    root.querySelectorAll('.section-title').forEach(function(st){
      var t=st.textContent||'';
      if(/开始玩|游戏|练习/.test(t)) st.innerHTML='<span class="st-ico">🎮</span>练习栏目 <span class="pq-kicker2">Secciones</span>';
      else if(/任务地图|主题/.test(t)) st.innerHTML='<span class="st-ico">🧭</span>目的地 <span class="pq-kicker2">Destinos</span>';
    });
  }

  /* 3. 学习手账：把掌握度/速度/口诀/统计/等级/勋章/设置收纳进同一折叠区 */
  function buildJournal(){
    var root=document.querySelector('#homePage .container'); if(!root) return;
    var q=function(s){return root.querySelector(s);};
    var mastery=q('.mastery-panel'), speed=q('.speed-bar'), mnemonic=q('.mnemonic-bar'),
        stats=q('.stats-row'), level=q('.level-row'), achievements=q('.achievements'), settings=q('.settings-bar');
    var medalTitle=null;
    root.querySelectorAll('.section-title').forEach(function(st){ if(/勋章/.test(st.textContent||'')) medalTitle=st; });
    refineSections(root);

    if(!root.querySelector('.pq-journal')){
      var details=document.createElement('details');
      details.className='pq-journal';
      details.innerHTML='<summary><span>📒 学习手账 <span style="font-size:10px;letter-spacing:1px;color:var(--faint);font-weight:600;text-transform:uppercase">Bitácora</span></span><span class="pq-j-arrow">▾</span></summary><div class="pq-j-body"></div>';
      var body=details.querySelector('.pq-j-body');
      [mastery,speed,mnemonic,stats,level,medalTitle,achievements,settings].forEach(function(el){ if(el) body.appendChild(el); });
      var themeGrid=q('#themeGrid');
      if(themeGrid) themeGrid.after(details); else root.appendChild(details);
    }
  }

  /* 5. 阿蛋编辑部：折叠、一句话 */
  function refineTip(){
    var root=document.querySelector('#homePage .container'); if(!root) return;
    var tip=root.querySelector('.tip-bar');
    if(tip&&!root.querySelector('.pq-tip')){
      var d=document.createElement('details');
      d.className='pq-tip';
      d.innerHTML='<summary>📮 阿蛋编辑部 · 一句话贴士</summary>'+
        '<div class="pq-t-body">点任意西语词句都能听发音；例句为旅行场景原创，融合西班牙本土与拉美口语，难度 A1–C1。遇到陌生表达先看场景提示，大胆跟读。</div>';
      tip.replaceWith(d);
    }
  }

  /* 6. 版权：全局极简单句（权威、不堆砌）；首页内重复版权栏移除，统一由 footer 承担 */
  var PQ_COPY_TEXT='本工具为自主研发西语学习辅助产品，非塞万提斯学院官方出品，所有题目为 DELE 考点原创改编，仅供个人学习，禁止二次售卖。';
  function refineCopyright(){
    var root=document.querySelector('#homePage .container');
    if(root){
      var cb=root.querySelector('.copyright-bar'); if(cb) cb.remove();
      var pc=root.querySelector('.pq-copy'); if(pc) pc.remove();
    }
    var footer=document.querySelector('footer');
    if(footer){
      footer.textContent=PQ_COPY_TEXT;
      footer.removeAttribute('style');
      footer.classList.add('pq-copy');
    }
  }

  /* 7. 做题页：专注模式开关（隐藏词篮/考点深挖，只看题） */
  function mountFocus(){
    var qp=document.getElementById('quizPage'); if(!qp) return;
    var meta=qp.querySelector('.quiz-meta');
    if(meta&&!meta.querySelector('.pq-focus-btn')){
      var b=document.createElement('button');
      b.type='button'; b.className='pq-focus-btn'; b.textContent='专注';
      b.onclick=function(){
        qp.classList.toggle('focus'); b.classList.toggle('on');
        b.textContent=qp.classList.contains('focus')?'完整':'专注';
      };
      meta.appendChild(b);
    }
  }

  /* 8. 唯一主页落地：无论哪一层初始化，最终都落在杂志主页 homePage。
     收敛：不再覆盖 initHome，改为注册首页渲染后回调（排最后执行，压过前面的 mapPage 落点）。 */
  function routeHome(){
    if(typeof window.onHome==='function'){
      window.onHome(function(){ try{ window.showPage('homePage'); }catch(e){} });
    }
    /* 已解锁用户走「记住我」时，bootLock 可能在本脚本注册前已先行落地 mapPage，
       注册后立即把落点拉回杂志主页（锁屏时 appRoot 隐藏，此调用不可见、无副作用）。 */
    try{ window.showPage('homePage'); }catch(e){}
  }

  /* 9. 审核修复：说一说(describe)题点「看参考描述」后未置 state.answered，
     会被 nextQ 的「必须先作答」防护锁拦截，用户卡死无法翻页。
     口语自评不计对错，reveal 后应视为本页完成。包装实现，不改原函数。 */
  function patchDescribe(){
    try{
      if(typeof window.revealDescribe!=='function'||window.revealDescribe.__pq)return;
      var orig=window.revealDescribe;
      var w=function(){
        var r=orig.apply(this,arguments);
        try{ if(typeof state!=='undefined') state.answered=true; }catch(e){}
        return r;
      };
      w.__pq=true; window.revealDescribe=w;
    }catch(e){}
  }

  ready(function(){
    try{
      buildLock();
      buildCover();
      buildJournal();
      refineTip();
      refineCopyright();
      mountFocus();
      routeHome();
      patchDescribe();
    }catch(e){ if(window&&window.console) console.error('Paquete UI init error:',e); }
  });
})();
