function openGuide(id){
 const g=V3_GUIDE.find(x=>x.id===id)||V3_GUIDE[0];
 let ov=document.getElementById('guideOverlay');
 if(!ov){
  ov=document.createElement('div');ov.id='guideOverlay';document.body.appendChild(ov);
 }
 let tabs='<div class="gd-tabs">'+V3_GUIDE.map(x=>`<div class="gd-tab${x.id===g.id?' on':''}" onclick="openGuide('${x.id}')">${x.flag} ${x.name}</div>`).join('')+'</div>';
 let body='';
 body+=`<div class="gd-hero" style="${g.hero}"><h3>${g.flag} ${g.name} <span style="font-weight:600;font-size:13px">· ${g.en}</span></h3><p>${g.intro}</p></div>`;
 if(g.best)body+=`<div class="gd-grid2" style="margin-bottom:12px"><div class="gd-mini"><div class="gm-k">🗓️ 最佳季节</div><div class="gm-v" style="font-size:12px">${g.best}</div></div></div>`;
 if(g.cities)body+=`<div class="gd-sec"><h4>🏙️ 不可错过的城市与体验</h4><ul>${g.cities.map(c=>`<li><b>${c[0]}</b> — ${c[1]}</li>`).join('')}</ul></div>`;
 if(g.food)body+=`<div class="gd-sec"><h4>🍽️ 必吃清单</h4><ul>${g.food.map(f=>`<li>${f}</li>`).join('')}</ul></div>`;
 if(g.customs)body+=`<div class="gd-sec"><h4>📋 实用要点</h4><ul>${g.customs.map(c=>`<li><b>${c[0]}</b> ${c[1]}</li>`).join('')}</ul></div>`;
 if(g.phrases)body+=`<div class="gd-sec"><h4>💬 小西语角（点🔊跟听）</h4><div class="gd-phrases">${g.phrases.map((ph,pi)=>`<div class="gd-phrase"><button onclick="speak(V3_GUIDE.find(x=>x.id==='${g.id}').phrases[${pi}][0])" aria-label="朗读">🔊</button><span class="gp-es">${ph[0]}</span><span class="gp-zh">${ph[1]}</span></div>`).join('')}</div></div>`;
 if(g.tips)body+=`<div class="gd-tip">💡 <b>旅行者笔记：</b>${g.tips}</div>`;
 ov.innerHTML=`<div class="gd-top"><button class="gd-close" onclick="closeGuide()">✕</button><h2>🌍 旅行百科 · Guía práctica</h2></div>${tabs}<div class="gd-body">${body}</div>`;
 ov.classList.add('show');ov.scrollTop=0;
 try{document.querySelector('.page.active')&&document.body.style.setProperty('overflow','hidden')}catch(e){}
}
function closeGuide(){const ov=document.getElementById('guideOverlay');if(ov)ov.classList.remove('show');try{document.body.style.removeProperty('overflow')}catch(e){}}

/* ================= 航线视图渲染 ================= */
function v3RenderStages(){
 const grid=document.getElementById('themeGrid');
 if(!grid)return;
 const d=getData();
 let html=`<div class="stage-wrap">`;
 html+=`<div class="loop-strip"><span style="font-size:11px;font-weight:900;color:#F5F5F5;margin-right:2px">🔁 学习闭环</span>`+
  V3_LOOP.map((l,i)=>`<span class="loop-chip">${l[0]}</span>`+(i<V3_LOOP.length-1?'<span class="loop-arrow">→</span>':'')).join('')+`</div>`;
 // 第0站 入门站
 html+=`<div class="stage-head"><span class="st-ico">🐣</span>第0站 · 入门站<span class="st-lv">A1 · 从零出发</span></div>`;
 html+=`<div class="stage-cards">
  <div class="stage-card" onclick="openBase()"><span class="tc-ico">🌱</span><span class="tc-name">发音与地基</span><span class="tc-sub">字母 · 数字 · 时间</span><div class="tc-bar"><div class="tc-fill" style="width:${v3BasePct()}%"></div></div></div>
  <div class="stage-card" onclick="openCard(130)"><span class="tc-ico">🔤</span><span class="tc-name">五个元音</span><span class="tc-sub">a e i o u</span></div>
  <div class="stage-card" onclick="openCard(168)"><span class="tc-ico">👄</span><span class="tc-name">辅音发音</span><span class="tc-sub">b/v · c/z · r</span></div>
  <div class="stage-card guide" onclick="openGuide('kit')"><span class="tc-ico">🧰</span><span class="tc-name">实用锦囊</span><span class="tc-sub">插头 · 小费 · 急救句</span></div>
 </div>`;
 // 第1-4站
 V3_STAGES.forEach(st=>{
  html+=`<div class="stage-head"><span class="st-ico">${st.ico}</span>${st.name}<span class="st-lv">${st.lv}</span></div>`;
  html+=`<div class="stage-cards">`;
  st.idx.forEach(i=>{
   const sec=SECTIONS[i];if(!sec)return;
   const cs=cardsOfSection(sec.id);
   const done=cs.filter(c=>d.learned&&d.learned[c.id]).length;
   const pct=cs.length?Math.round(done/cs.length*100):0;
   const nT=questionsOfSection(sec.id).length,nW=wordsOfSection(sec.id).length;
   html+=`<div class="stage-card" onclick="openSection(${sec.id})">${pct>=100?'<span class="tc-badge">破壳🐣</span>':''}<span class="tc-ico">${sec.icon}</span><span class="tc-name">${sec.name}</span><span class="tc-sub">${nT} 题 · ${nW} 词</span><div class="tc-bar"><div class="tc-fill" style="width:${pct}%"></div></div></div>`;
  });
  html+=`<div class="stage-card" onclick="v3ToggleSummary(this)" style="display:flex;flex-direction:column;justify-content:center"><span class="tc-ico">🧶</span><span class="tc-name">本站小结</span><span class="tc-sub">点击展开</span></div>`;
  html+=`</div><div class="stage-summary" style="display:none"><b>${st.name} 知识归纳：</b>${st.summary}</div>`;
 });
 // 旅行百科卡
 html+=`<div class="stage-head"><span class="st-ico">🌍</span>旅行百科 · 科普拓展<span class="st-lv">GUIA PRÁCTICA</span></div>`;
 html+=`<div class="stage-cards">`+V3_GUIDE.map(g=>`<div class="stage-card guide" onclick="openGuide('${g.id}')"><span class="tc-ico">${g.flag}</span><span class="tc-name" style="font-size:12px">${g.name}</span><span class="tc-sub">攻略 · 西语角</span></div>`).join('')+`</div>`;
 html+=`<div class="stage-summary" style="display:block"><b>航线说明：</b>从破壳（A1 字母发音）到融入（C1 与母语者无障碍交流），每一站都是一段真实旅程；学卡→测验→错题池→生词本→复习→里程碑，闭环转起来，旅程走到底。🌍✈️</div>`;
 html+=`</div>`;
 grid.innerHTML=html;
 grid.style.display='block';
}
function v3ToggleSummary(el){
 const sm=el.closest('.stage-cards').nextElementSibling;
 if(sm&&sm.classList.contains('stage-summary')){sm.style.display=sm.style.display==='none'?'block':'none';el.querySelector('.tc-sub').textContent=sm.style.display==='none'?'点击展开':'点击收起';}
}
function v3BasePct(){
 try{const el=document.querySelector('.vr-state.cur,#v8Route');if(el){const m=(document.getElementById('v8Route').innerText.match(/(\d+)%/)||[]);if(m)return +m[1];}}catch(e){}
 return 0;
}
/* 接管首页初始化：渲染航线视图（原主题网格被航线视图替换，数据与逻辑共用）。
   收敛：改为首页渲染后回调，不再覆盖 initHome。 */
(function(){
 if(typeof window.onHome!=='function')return;
 window.onHome(function(){ try{v3RenderStages();}catch(e){console.warn('v3 stage render:',e);} });
})();
