function v3Norm(w){return w.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
const V3_IDX={};Object.keys(V3_LEX).forEach(k=>{if(V3_LEX[k]&&V3_LEX[k].pos&&V3_LEX[k].pos[0]!=='_')V3_IDX[v3Norm(k)]=k});
/* ===== HTML 标注：仅包裹词典命中的整词（跳过标签内部）===== */
function v3AnnotateHTML(html){
 return html.replace(/>([^<]+)</g,(m,txt)=>{
  const nt=txt.replace(/[A-Za-zÁÉÍÓÚÑáéíóúñü]+/g,w=>{
   const key=V3_IDX[v3Norm(w)];if(!key)return w;
   const hit=V3_IDX[v3Norm(w)];
   const cur=v3Norm(w);
   // 命中词典原形或简单屈折（复数 s/es、常规变位结尾以词典键为前缀）
   const base=v3Norm(hit);
   if(cur===base||cur===base+'s'||cur===base+'es'||cur===base.slice(0,-1)+ (base.endsWith('e')?'':'')) return `<span class="v3w" data-w="${hit}">${w}</span>`;
   // 常规动词变位/形容词阴阳性：词干匹配（≥4字符词干）
   if(cur.startsWith(base.slice(0,Math.max(4,base.length-2))))return `<span class="v3w" data-w="${hit}">${w}</span>`;
   return w;
  });
  return '>'+nt+'<';
 });
}
