function v3ShowLex(word){
 const e=V3_LEX[word];if(!e)return;
 let ov=document.getElementById('v3lex');
 if(!ov){ov=document.createElement('div');ov.id='v3lex';document.body.appendChild(ov);}
 const rootHtml=e.root?(()=>{
   const chips=[];
   if(e.root.pre)chips.push(`<span class="lx-chip pre">${e.root.pre[0]}<i>${e.root.pre[1]}</i></span>`);
   chips.push(`<span class="lx-chip rad">${e.root.rad[0]}<i>${e.root.rad[1]}</i></span>`);
   if(e.root.suf)chips.push(`<span class="lx-chip suf">${e.root.suf[0]}<i>${e.root.suf[1]}</i></span>`);
   return `<div class="lx-root">${chips.join('<span class="lx-plus">＋</span>')}</div>`;
 })():'';
 ov.innerHTML=`
 <div class="lx-head"><span class="lx-w">${word}</span><span class="lx-pos">${e.pos}</span><button onclick="v3CloseLex()">✕</button></div>
 <div class="lx-body">
  <div class="lx-zh">${e.zh}</div>
  ${rootHtml?`<div class="lx-sec"><h5>🧠 词根词缀 · 记忆解剖</h5>${rootHtml}<div class="lx-mn">💡 ${e.mn}</div></div>`:''}
  ${e.gram?`<div class="lx-sec"><h5>📐 语法解析</h5><p>${e.gram}</p></div>`:''}
  ${e.col?`<div class="lx-sec"><h5>🔗 固定搭配</h5><p>${e.col}</p></div>`:''}
  ${e.ex&&e.ex[0]?`<div class="lx-sec"><h5>✏️ 中西对照例句</h5><div class="lx-ex"><button onclick="speak(V3_LEX['${word}'].ex[0])">🔊</button><span>${e.ex[0]}<br><span class="lx-ezh">${e.ex[1]}</span></span></div></div>`:''}
  <div class="lx-sec" style="text-align:center;border-style:dashed"><button onclick="speak('${word.replace(/'/g,"\\'")}')" style="width:auto;padding:6px 18px;font-weight:900">🔊 听发音</button></div>
 </div>`;
 ov.classList.add('show');
}
