const V3X_TENSE_CLUES='<b>时间线索只提示、不决定时态，最终看语境：</b><br>· ayer / anoche / el año pasado：常见于简单过去时（Ayer fui al cine.）<br>· todos los días / siempre：现在的习惯常用现在时（Todos los días estudio español.），也可描述过去习惯<br>· mañana / la semana que viene：将来表达，可用简单将来时或 ir a + 不定式、现在时表安排（Mañana estudiaré. / Voy a estudiar.）<br>· ya / hoy：依语境判断（Hoy he estudiado mucho. / Hoy estudio.）<br>· antes / de pequeño / mientras：过去习惯或背景常用未完成过去时（De pequeño jugaba al fútbol.）<br>· si + 过去虚拟式：非现实或假设条件（Si tuviera tiempo, viajaría más.）<br>· ojalá + 虚拟式：表愿望，时态随愿望与现实的距离变化（Ojalá tenga tiempo. / Ojalá tuviera tiempo.）<br>⚠ 西班牙与拉美在现在完成时的使用频率和时间范围上不同，不能把单一地区习惯当作唯一标准。';
function v3xCol(w,e){
 const pos=e[0];
 if(pos==='v')return 'quiero '+w+' 我想… · ¿puedes '+w+'? 你能…吗 · voy a '+w+' 我打算…';
 if(pos==='adj.')return 'muy '+w+' 很… · un poco '+w+' 有点… · está '+w;
 if(pos==='adv.')return w+' 修饰形容词/动词：'+w+' bonito · '+w+' caro';
 if(pos.startsWith('s.')){const A=v5Arts(w);return A.ind+' '+w+' 一个… · sin '+w+' 没有… · '+(A.fem?'mucha':'mucho')+' '+w+' 很多…';}
 return '常用搭配：'+w;
}
/* ===== 场景化词卡引擎：对话 / 造句一律取真实旅行语料或真实场景句型 =====
   旧模板缺陷（全库 5175 词）：4280 词用「¿qué significa «X»?／记到小本子」讲解词义，
   3097 词用「Necesito un X／¿Dónde puedo comprar un X」硬套购物句；
   对呼救感叹词、功能问句、客套语块、虚词、非实物名词全是病句。
   新引擎按「功能 → 真实语料 → 词性」分派，不造无意义句。 */
function v3SceneKey(w){
 return String(w||'').toLowerCase().trim()
  .replace(/[¡!¿?]+/g,'')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/^(el|la|los|las|un|una)\s+/i,'').trim();
}
/* 语料在脚本执行期（V3X_DIALOG 预生成）尚未就绪，此时走轻量模板；
   渲染时（页面加载完成）再取真实例句，避免启动卡顿与 TDZ 报错。 */
function v3Ready(){try{return typeof V9_SDICT!=='undefined'&&Object.keys(V9_SDICT).length>0}catch(e){return false}}
function v3Has(sentence,w){
 const k=v3SceneKey(w);if(!k)return false;
 const s=String(sentence||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 if(s.indexOf(k)>=0)return true;
 const toks=k.split(/\s+/).filter(t=>t.length>=4);
 return toks.length>1&&toks.some(t=>s.indexOf(t)>=0);
}
/* 场景词典人工例句优先 → 题库真实例句；只收真正包含该词、且无占位符的句子 */
function v3Real(w){
 if(!v3Ready())return null;
 let ex=[],cols=[],scene='';
 try{const sd=v9DictOf(w);if(sd){
   scene=sd.scene||'';
   if(sd.exs&&sd.exs.length)ex=sd.exs.slice(0,3);
   cols=(sd.cols||[]).slice(0,2).map(c=>{
    const m=String(c).match(/^([^\u4e00-\u9fa5]+?)\s*([\u4e00-\u9fa5].*)$/);
    return m?[m[1].trim(),m[2].trim()]:[String(c).trim(),''];
   });
 }}catch(e){}
 if(!ex.length){try{ex=(v9ExFor(w,3)||[]).slice(0,3)}catch(e){}}
 ex=ex.filter(x=>x&&x[0]&&!/[{}]/.test(x[0])&&v3Has(x[0],w));
 return (ex.length||cols.length)?{ex:ex.slice(0,2),cols:cols,scene:scene}:null;
}
function v3Blank(s,w){
 const k=v3SceneKey(w);if(!k)return String(s);
 try{
  const flex=k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')
              .replace(/[aeiou]/g,ch=>({a:'[aá]',e:'[eé]',i:'[ií]',o:'[oó]',u:'[uú]'}[ch]||ch));
  return String(s).replace(new RegExp(flex,'i'),'＿＿＿');
 }catch(e){return String(s)}
}
