function v3SocialDrill(s,dl){
 const b=v3Blank(dl[0][0],s);
 return ['照这句换个词说一遍：',b!==dl[0][0]?b:'照这句的结构，换掉一个词','参考：'+dl[0][0]];
}
function v3IsVirtual(s,pos,zh){
 const lw=String(s||'').toLowerCase().trim();
 if(/\s/.test(lw)||/mente$/.test(lw))return true;
 if(/^(adv|prep|conj|interj)/.test(String(pos||'')))return true;
 if(/^(a|ante|bajo|con|contra|de|desde|en|entre|hacia|hasta|para|por|según|sin|sobre|tras|y|o|pero|porque|que|si|cuando|donde|como|mientras|aunque|más|menos|muy|poco|mucho|nada|algo|todo|tanto|bastante|demasiado|bien|mal|así|solo|también|tampoco|siempre|nunca|jamás|ya|hoy|ayer|mañana|ahora|antes|después|luego|entonces|pronto|tarde|temprano|aquí|allí|allá|acá|cerca|lejos|dentro|fuera|arriba|abajo|delante|detrás|encima|debajo|despacio|rápido|claro|seguro|quizá|acaso)$/i.test(lw))return true;
 return false;
}
function v3NounPhrase(s){
 const bare=String(s).replace(/^(el|la|los|las|un|una)\s+/i,'');
 let art='un';try{art=v5Arts(bare).ind}catch(e){}
 return {bare:bare,art:art};
}
function v3Scene(w,e){
 const s=String(w||'').trim();
 const pos=String((e&&e[0])||''),zh=String((e&&e[1])||'').split(/[；;·]/)[0].trim();
 let dl,dr,mode='dialog';
 if(/^¿/.test(s)){                                   /* ① 功能问句：原句 + 真实回答 */
  const a=v3Answer(s);
  dl=[[s,zh||'（提问）'],[a[0],a[1]]];
  dr=['照这个句型问一句，换个词就是新句子：',v3AskTpl(s),'参考：'+s];
 }else if(/^¡/.test(s)){                            /* ② 呼救 / 感叹：应急现场 */
  dl=[[s,zh||'（呼救）'],['¿Dónde está? ¿Qué pasa?','你在哪？怎么了？']];
  dr=['用 '+s+' 说一句紧急情况：',s+' + 简短情况','参考：'+s+' ¡No puedo respirar!'];
 }else{
  const so=v3Social(s);
  if(so){dl=so;dr=v3SocialDrill(s,so);}            /* ③ 社交客套 */
  else{
   const R=v3Real(s);
   if(R&&(R.ex.length||R.cols.length)){          /* ④ 只展示库里真人写的例句/搭配，不编造应答 */
    const items=R.ex.slice(0,2).map(x=>[x[0],x[1]||'']);
    for(const c of R.cols){if(items.length>=2)break;if(c&&c[0]&&!/[{}]/.test(c[0]))items.push([c[0],c[1]||'常用搭配']);}
    dl=items.length?items:[[s,zh||'见上方例句']];
    const a=dl[0],bl=v3Blank(a[0],s);
    dr=['照真实例句换个词练：',bl!==a[0]?bl:'句型不变，换掉句中一个词','参考：'+a[0]];
    mode='usage';
   }else if(pos==='v'&&!/\s/.test(s)){                            /* ⑤ 动词：旅行安排 */
    dl=[['¿Qué vas a hacer hoy?','你今天打算做什么？'],['Voy a '+s+' por la mañana.','我上午要'+zh+'。']];
    dr=['用 '+s+' 说一句今天的安排：','Hoy voy a '+s+'.','参考：Hoy voy a '+s+' por la mañana.'];
   }else if(/^adj/.test(pos)&&!/\s/.test(s)){                      /* ⑥ 形容词：描述住处 / 城市 */
    dl=[['¿Cómo es el hotel?','酒店怎么样？'],['Es muy '+s+' y está céntrico.','很'+zh+'，位置也居中。']];
    dr=['用 '+s+' 描述你住的地方：','El hotel es muy '+s+'.','参考：El pueblo era '+s+' y tranquilo.'];
   }else if(v3IsVirtual(s,pos,zh)){                                /* ⑦ 虚词/副词/固定短语：不套名词句 */
    dl=[[s,zh||pos],['整块使用：看上方「例句」里它怎么进句子','虚词／固定短语不单独造句']];
    dr=['跟着上方例句把这个词换进去练：','（见「例句」与「常见搭配」）','参考：见上方「例句」'];
    mode='usage';
   }else if(/^s\.|^名词/.test(pos)&&!/\s/.test(s)){                /* ⑧ 无语料名词：给真实搭配，不造 Es un X */
    let col=s;
    try{const sd=v9DictOf(s);col=(sd&&sd.cols&&sd.cols.length)?sd.cols[0]:String(v3xCol(s,{0:pos,1:zh})).split(/\s*·\s*/)[0].trim()}catch(err){}
    col=String(col).split(/[\u4e00-\u9fa5]/)[0].trim()||col;  /* 去掉「一个…」之类中文占位，只留西语搭配 */
    dl=[[col,'真实搭配（整块记，别拆开）'],[s,'按搭配进句子；非旅行高频词先认词']];
    dr=['把这个搭配用进一句话：',col,'参考：'+col];
    mode='usage';
   }else{                                                          /* ⑨ 其它：给词形与用法指引，不硬造句 */
    dl=[[s,zh||pos],['整块使用：看上方「例句」里它怎么进句子','跟着例句与搭配记']];
    dr=['跟着上方例句把这个词换进去练：','（见「例句」与「常见搭配」）','参考：见上方「例句」'];
    mode='usage';
   }
  }
 }
 return {dl:dl,dr:dr,mode:mode};
}
function v3xDialog(w,e){return v3Scene(w,e).dl}
function v3xDrill(w,e){return v3Scene(w,e).dr}
function v3xReplyGuide(w){
 if(/^¿Dónde/.test(w))return ['提问来源：dónde（哪里）+ estar → 问位置。','回复逻辑：Está + 方位词（en/a la derecha/junto a…），再补一句距离。'];
 if(/^¿Cuánto/.test(w))return ['提问来源：cuánto（多少）问价格/数量。','回复逻辑：Es/Son + 数字 + moneda；或 Cuesta + 价格。'];
 if(/^¿A qué hora/.test(w))return ['提问来源：a qué hora 问钟点。','回复逻辑：A las + 时刻（y cuarto/y media/menos cuarto）。'];
 if(/^¿Cómo/.test(w))return ['提问来源：cómo 问方式/状态/表达。','回复逻辑：直接给方法或释义：Se dice… / Se va por… / Muy bien, gracias…'];
 if(/^¿Puedo|^¿Se puede/.test(w))return ['提问来源：poder 表请求许可（礼貌万能句）。','回复逻辑：Sí, claro / Claro que sí / Lo siento, no se puede.'];
 if(/^¿Tiene|^¿Hay/.test(w))return ['提问来源：tener/haber 问有无（hay 不定指，tiene 定指）。','回复逻辑：Sí, tenemos… / No hay ninguno; le recomiendo…'];
 if(/^¿Habla|^¿Qué significa|^¿Puede repetir|^¿Más despacio/.test(w))return ['提问来源：沟通求助句，语言不通时的救命索。','回复逻辑：请求重复或放慢：Más despacio, por favor. / ¿Puede repetir?'];
 if(/^Necesito|^Quiero|^Estoy/.test(w))return ['提问来源：第一人称陈述需求（necesitar/querer/estar）。','回复逻辑：对方会补足信息：¿Para cuántas personas? / En seguida se lo traigo.'];
 return ['提问来源：旅行场景高频功能句。','回复逻辑：记住一问一答配对，角色扮演两次即入脑。'];
}
function v3xCard(word){
 const e=V3X_DATA.words[word];if(!e)return '';
 const pos=e[0],zh=e[1],ri=e[2],suf=e[3],src=e[4],pre=e[5];
 const root=ri!=null?V3X_DATA.roots[ri]:null;
 let rootHtml='';
 if(root){
  const chips=[];
  if(pre)chips.push('<span class="lx-chip pre">'+pre[0]+'<i>'+v5RootZh(pre[1])+'</i></span>');
  chips.push('<span class="lx-chip rad">'+root[0]+'<i>'+v5RootZh(root[1])+'</i></span>');
  if(suf&&suf[0]!=='—')chips.push('<span class="lx-chip suf">'+suf[0]+'<i>'+v5RootZh(suf[1])+'</i></span>');
  const seg=[];
  if(pre)seg.push(pre[0]+'（'+v5RootZh(pre[1])+'）');
  seg.push(root[0]+'（'+v5RootZh(root[1])+'）');
  if(suf&&suf[0]!=='—')seg.push(suf[0]+'（'+v5RootZh(suf[1])+'）');
  rootHtml='<div class="lx-sec"><h5>🧠 词根</h5><div class="lx-root">'+chips.join('<span class="lx-plus">＋</span>')+'</div>'
   +(seg.length>1?'<div class="lx-mn">记：'+seg.join(' ＋ ')+'</div>':'')+'</div>';
 }
 let gramHtml='<div class="lx-sec"><h5>📐 语法用法</h5><p>';
 if(pos==='v')gramHtml+='动词 · 词典形 '+word+'。'+V3X_TENSE_CLUES;
 else if(pos==='adj.')gramHtml+='形容词 · 阴阳性随名词：'+word+' / '+word.replace(/o$/,'a')+'；复数 +'+'s';
 else if(pos==='s.f.')gramHtml+='阴性名词 · 冠词 la/una'+(word.endsWith('a')?'':'（注意性属）');
 else if(pos==='s.m.')gramHtml+='阳性名词 · 冠词 el/un'+(word.startsWith('a')&&word.endsWith('a')?'（a- 阴性词单数用 el agua 型）':'');
 else if(pos==='adv.')gramHtml+='副词 · 修饰动词/形容词，不变形';
 else gramHtml+='词性：'+pos;
 gramHtml+='</p></div>';
 const isQ=/^¿/.test(word);
 const qHtml=isQ?(()=>{const g=v3xReplyGuide(word);return '<div class="lx-sec"><h5>❓ 问与答</h5><p>'+g[0]+'<br>'+g[1]+'</p></div>'})():'';
 const col=v3xCol(word,e);
 const SC=v3Scene(word,e),dl=SC.dl,mode=SC.mode;
 const dr=SC.dr;
 const saved=V3X_SAVED.includes(word);
 return '<div class="lx-head"><span class="lx-w">'+word+'</span><span class="lx-pos">'+pos+'</span><button onclick="v3CloseLex()">✕</button></div>'
 +'<div class="lx-body"><div class="lx-zh">'+zh+(src==='B'?'':' · <span style="font-size:10px;color:#409CFF">拉丁词根族</span>')+'</div>'
 +rootHtml+gramHtml+qHtml
 +'<div class="lx-sec"><h5>🔗 搭配</h5><p>'+col+'</p></div>'
 +'<div class="lx-sec"><h5>'+(mode==='usage'?'🎬 场景用法':'💬 场景对话')+'</h5>'
 +dl.map((x,i)=>'<div class="lx-ex"><button onclick="speak('+JSON.stringify(x[0]).replace(/"/g,'&quot;')+')">🔊</button><span><b style="color:'+(mode==='usage'?'#BDB0A0':(i%2===0?'#409CFF':'#D8A1B1'))+'">'+(mode==='usage'?'•':(i%2===0?'♂':'♀'))+' '+x[0]+'</b><br><span class="lx-ezh">'+x[1]+'</span></span></div>').join('')+'</div>'
 +'<div class="lx-sec" style="border-style:dashed"><h5>✍️ 造句</h5><p>'+dr[0]+'<br><span style="color:#BDB0A0">模板 '+dr[1]+'</span><br><span style="color:#409CFF">参考 '+dr[2]+'</span></p></div>'
 +'<div class="lx-sec" style="text-align:center"><button onclick="speak(\''+word.replace(/'/g,"\\'")+'\')" style="width:auto;padding:6px 18px;font-weight:900">🔊 听发音</button> '
 +'<button onclick="v3xSave(\''+word.replace(/'/g,"\\'")+'\')" style="width:auto;padding:6px 14px;font-weight:900;background:'+(saved?'#271F17':'#0A84FF')+';color:'+(saved?'#409CFF':'#FFFFFF')+'">'+(saved?'✓ 已收':'➕ 收进我的词库')+'</button></div></div>';
}
V3X_DIALOG={};
V3X_WORDS.forEach(w=>{const e=V3X_DATA.words[w];if(e)V3X_DIALOG[w]=v3xDialog(w,e)});
function v3xSave(w){
 const i=V3X_SAVED.indexOf(w);
 if(i>=0)V3X_SAVED.splice(i,1);else V3X_SAVED.push(w);
 v3xSet('v3xSaved',V3X_SAVED);
 const ov=document.getElementById('v3lex');if(ov&&ov.classList.contains('show'))ov.innerHTML=(window.v3Card?window.v3Card(w):v3xCard(w));
}
/* ===== 覆写解析弹层 ===== */
/* 收敛：不再覆盖 v3ShowLex（原实现会让 v3x 词库 5000+ 词的专属卡被后续 v5 覆盖）。
   此处仅补 v3x 词库的兜底卡渲染函数，由 showLex 内部按需回落调用。 */
window.v3xCard=window.v3xCard||function(word){return v3xCard(word)};
/* ===== 生词查询引擎（主页板块 · 全量 5116 词 · A-Z）===== */
function v3OpenDict(){
 let ov=document.getElementById('v3xdict');
 if(!ov){ov=document.createElement('div');ov.id='v3xdict';ov.className='v3x-bank';document.body.appendChild(ov);}
 v3xRenderDict('');
 ov.classList.add('show');
}
function v3CloseDict(){
 const ov=document.getElementById('v3xdict');
 if(!ov||!ov.classList.contains('show'))return;
 /* 退出性能修复：超长词表（5000+ 词 ≈ 30 万 px 文档）直接 display:none 会触发整页重新布局，
    手机端体感即为“退出卡顿”。改为：先淡出并隐藏，等两帧后脱离文档流、清空内容；下次打开时再重建。 */
 ov.classList.add('closing');
 ov.style.pointerEvents='none';
 requestAnimationFrame(()=>requestAnimationFrame(()=>{
  ov.classList.remove('show','closing');
  ov.style.pointerEvents='';
  try{ if(ov.__lazyIO){ov.__lazyIO.disconnect();ov.__lazyIO=null;} }catch(e){}
  ov.innerHTML=''; // 释放数百个词条节点
  ov.scrollTop=0;
 }));
}
function v3xRenderDict(q){
 const ov=document.getElementById('v3xdict');if(!ov)return;
 q=(q||'').trim();
 let words;
 if(q){
  const nq=v3Norm2(q);
  words=V3X_WORDS.filter(w=>{
   const e=V3X_DATA.words[w];
   return v3Norm2(w).includes(nq)||w.includes(q)||(e&&e[1].includes(q));
  }).slice(0,120);
 }else words=V3X_WORDS;
 /* A-Z 分组 */
 const groups={};
 words.forEach(w=>{const L=(w[0]||'#').toUpperCase();const k=/[A-ZÁÉÍÓÚÑ]/.test(L)?L:'#';(groups[k]=groups[k]||[]).push(w)});
 const letters=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'es'));
 let html='<div class="v3xb-top"><b>🔍 生词查询引擎 · Diccionario</b><span>'+V3X_WORDS.length+' 词 · 全量入库 · A-Z</span><button onclick="v3CloseDict()">✕</button></div>';
 html+='<div class="v3xd-search"><input id="v3xdInput" placeholder="输入西语或中文查询（如 hotel / 酒店 / viaj…）" value="'+q.replace(/"/g,'&quot;')+'" oninput="v3xSearch(this.value)"><button onclick="v3xdSpeak(0)">🔊</button></div>';
 html+='<div class="v3xd-az">'+letters.map(L=>'<a href="javascript:void(0)" onclick="v3xJump(\''+L+'\')">'+L+'</a>').join('')+'</div>';
 html+='<div class="v3xd-note">'+(q?('查询「'+q+'」：'+words.length+' 条结果（最多显示 120）'):'全部词条按 A-Z 顺序汇总 · 点击单词看「词根口诀 + 语法时态 + 搭配 + 男女对话 + 造句训练」')+'</div>';
 /* 性能修复：与词汇中心一致，字母组先占位、滚动临近再填充 */
 window.__v3xdPending=groups;
 letters.forEach(L=>{
  html+='<div class="v3xd-group" id="v3xdG-'+L+'" data-g="'+L+'"><div class="v3xd-letter">'+L+'</div><div class="v3xd-words" style="min-height:'+Math.min(groups[L].length,600)*62+'px"></div></div>';
 });
 html+='<div class="v3xb-top" style="margin-top:14px"><b>⭐ 我的词库（'+V3X_SAVED.length+'）</b></div><div class="v3xb-my">';
 html+=V3X_SAVED.length?V3X_SAVED.map(w=>'<span class="v3xb-w" onclick="v3ShowLex(\''+w.replace(/'/g,"\\'")+'\')">'+w+'</span>').join(''):'<span style="color:#9A9A9A">解析卡里点「➕ 收进我的词库」，生词会落到这里。</span>';
 html+='</div>';
 ov.innerHTML=html;
 v3xdAttachLazy(ov);
}
