/* ===== 题库注解·导读层（全题库：每题西语必有导读 + 生词注解 chips）===== */
const V3X_KIND_GUIDE={
 es2zh:'先读西语题干，再对照中文释义选项；拿不准的词点下方注解词看解析。',
 zh2es:'读中文题意，回忆对应西语表达；点注解词复习词形与搭配。',
 listen:'先听音频抓关键词，再选义；听完可看注解词复述一遍。',
 fill:'通读句子判断缺词词性（名/动/形），点注解词确认变形规则。',
 order:'先找主语和动词定骨架，再按「主—动—补」排序；注解词提示搭配。',
 situation:'场景选择题：先定位场景（机场/餐厅/酒店…），选最地道的一句。',
 judge:'对照原句与译文，抓动词时态和否定词是否一致。',
 error_correction:'先扫动词变位与性数一致，再查冠词介词；注解词给出正确用法。',
 describe:'按「是什么—什么样子—感受」三步组织句子，注解词可当句料。',
 gapfill:'先通读全文抓主线，再回填；点文中虚线词看词根解析。',
 longlisten:'先看问题再听，听两遍：一遍抓大意，一遍补细节；提交后全文可点词。'
};
function v3xExtractEs(q){
 const parts=[];
 ['q','s','hint','ref','article'].forEach(k=>{if(typeof q[k]==='string')parts.push(q[k])});
 if(Array.isArray(q.o))parts.push(q.o.join(' '));
 if(Array.isArray(q.tokens))parts.push(q.tokens.join(' '));
 if(typeof q.a==='string')parts.push(q.a);
 if(Array.isArray(q.a))parts.push(q.a.join(' '));
 return parts.join(' ');
}
function v3xAnnotateQuestion(q){
 const es=v3xExtractEs(q);
 const seen={},hits=[];
 const re=/[A-Za-zÁÉÍÓÚÑÜáéíóúüñ]+/g;let m;
 while((m=re.exec(es))&&hits.length<8){
  const raw=m[0];const key=V3X_IDX[v3Norm2(raw)]||(V3_LEX[raw]?raw:null);
  if(!key||seen[key])continue;seen[key]=1;
  const e=V3X_DATA.words[key]||V3_LEX[key];
  hits.push({w:key,zh:(e&&(e[1]||e.zh))||''});
 }
 const kindName=(TYPE_INFO[q.kind]&&TYPE_INFO[q.kind].name)||q.kind;
 const scene=(q.scene||THEMES[q.theme-1]&&THEMES[q.theme-1].name)||'旅行场景';
 const guide=V3X_KIND_GUIDE[q.kind]||'先读题干，再作答；点注解词看解析。';
 let chipHtml=hits.length
  ?hits.map(h=>'<span class="v3xa-chip" onclick="event.stopPropagation();v3ShowLex(\''+h.w.replace(/'/g,"\\'")+'\')">'+h.w+'<i>'+h.zh+'</i></span>').join('')
  :'<span class="v3xa-none">题干为常用句式，逐词见下方解析卡与全文点词。</span>';
 return '<div class="v3xa-bar" onclick="event.stopPropagation()"><div class="v3xa-guide">📖 <b>导读</b>｜'+scene+' · '+kindName+'：'+guide+'</div>'
  +'<div class="v3xa-chips"><b>🔍 生词注解</b>'+chipHtml+'</div></div>';
}
