/* —— 对话篇·男女分声连播：逐句按说话人性别选声，走统一队列串行 —— */
function v4PlayDialog(t,c){
 try{
  const ds=V4_DIALOGS[t];if(!ds||!ds[c])return;
  const d=ds[c];
  if(!('speechSynthesis' in window)){speak(d.lines.map(l=>l.es).join(' '));return;}
  refreshVoices();
  SpeechEngine.stop();
  /* 逐句按性别入队：长句由调度器自动分段，仍用同一说话人的声音 */
  d.lines.forEach((l,i)=>{
   if(i===0)SpeechEngine.play(l.es,l.who,{});
   else SpeechEngine.push(l.es,l.who);
  });
 }catch(e){ try{speak(d.lines.map(l=>l.es).join(' '))}catch(_){} }
}
