/* —— 辅助退出：一键退出当前层（解析卡→词汇中心→杂志→导读→回主页），每页可达 —— */
function assistExit(){
 try{
  const lex=document.getElementById('v3lex');
  if(lex&&lex.classList.contains('show')){v3CloseLex();return;}
  const dict=document.getElementById('v3xdict');
  if(dict&&dict.classList.contains('show')){v3CloseDict();return;}
  const mag=document.getElementById('v4mag');
  if(mag){if(typeof v4CloseMag==='function')v4CloseMag();else mag.remove();return;}
  const guide=document.getElementById('guideOverlay');
  if(guide&&guide.classList.contains('show')){if(typeof closeGuide==='function')closeGuide();return;}
  const home=document.getElementById('homePage');
  if(home&&!home.classList.contains('active')&&typeof showPage==='function'){showPage('homePage');return;}
 }catch(e){}
}
function addAssistBtn(){
 if(document.getElementById('assistBtn'))return;
 if(!(isSessionLocked()||autoLoginValid()))return; // 锁屏态不渲染
 const b=document.createElement('button');
 b.id='assistBtn';b.className='assist-exit';b.innerHTML='↩<span>退出</span>';
 b.onclick=assistExit;
 document.body.appendChild(b);
}
/* —— 入口：登录后默认进入杂志 + 原首页加返回按钮 —— */
(function(){
 V4_DIALOGS=v4BuildDialogs();
 /* 登录进入后默认显示杂志封面。
    收敛：不再覆盖 window.enterApp，改为注册进入后回调，避免多层覆盖导致 hook 丢失。 */
 if(typeof window.onEnter==='function')window.onEnter(v4EnterHook);
 function v4EnterHook(){
  /* 旅行工具模式：登录后不自动弹出杂志封面，改由速查台「📖 旅行刊」入口打开 */
  try{addBtn()}catch(e){}        // 解锁后再挂浮标（addBtn 内部仍会拒锁屏态）
  try{addAssistBtn()}catch(e){}  // 解锁后挂「辅助退出」按钮
 }
 // 原首页顶部插入「回到杂志」悬浮按钮（仅解锁态可见，密码页绝不出现）
 function addBtn(){
  if(document.getElementById('v4fab'))return;
  if(!(isSessionLocked()||autoLoginValid()))return; // 锁屏态绝不渲染浮标 → 根除"杂志浮标"绕过密码通道
  const b=document.createElement('button');
  b.id='v4fab';b.className='v4-fab';b.innerHTML='📕<span>杂志</span>';
  b.onclick=function(){v4OpenMag('cover')};
  document.body.appendChild(b);
 }
 setTimeout(addBtn,600);
 // showPage 回 homePage 时保证按钮在（解锁态才成立，addBtn 内部已把关）
 const origSP=window.showPage;
 if(typeof origSP==='function'){
  window.showPage=function(){const r=origSP.apply(this,arguments);try{addBtn()}catch(e){}return r};
 }
})();

