 return {word,base,pos,zh,senses,root,e,L,
  gram:(L&&L.gram)||(l2&&l2.gram)||(X&&X.gram)||'',col:(L&&L.col)||(l2&&l2.col)||(X&&X.col)||'',mn:(L&&L.mn)||(X&&X.mn)||'',src:(e&&e[4])||''};
