/* —— 查询层：惰性建索引（数据分多批写入，索引必须在最后建） —— */
let V9_IDX=null;
function v9NormKey(w){
 return String(w==null?'':w).toLowerCase()
  .replace(/^[¿¡«"'(\[]+/,'')
  .replace(/[.!?»"')\]]+$/,'')
  .trim();
}
function v9Index(){
 if(V9_IDX)return V9_IDX;
 const m={};
 Object.keys(V9_SDICT).forEach(k=>{
  const it=V9_SDICT[k];
  m[k.toLowerCase()]=it;
  m[v9NormKey(k)]=it;
  const bare=k.replace(/^(el|la|los|las|un|una|unos|unas)\s+/i,'');
  if(bare!==k)m[v9NormKey(bare)]=it;
  /* 对照词条（「el coche / el carro」这类）拆成两侧别名，单独查任一侧也能命中 */
  if(k.indexOf('/')>=0){
   k.split('/').forEach(function(part){
    var p=String(part||'').trim();
    if(p.length>2&&/[a-záéíóúüñ]/i.test(p)){
     var pb=p.replace(/^(el|la|los|las|un|una|unos|unas)\s+/i,'');
     if(!m[p.toLowerCase()])m[p.toLowerCase()]=it;
     if(!m[v9NormKey(p)])m[v9NormKey(p)]=it;
     if(pb&&pb!==p&&!m[v9NormKey(pb)])m[v9NormKey(pb)]=it;
    }
   });
  }
 });
 V9_IDX=m;return m;
}
/* 查一个词的场景词典条目；查不到返回 null */
function v9DictOf(w){
 const raw=String(w==null?'':w);
 if(!raw)return null;
 const m=v9Index();
 const r=m[raw.toLowerCase()]||m[v9NormKey(raw)]||null;
 if(!r)return null;
 const cols=String(r[3]||'').split('｜').map(s=>s.trim()).filter(Boolean);
 const seg=String(r[4]||'').split('｜');
 const exs=[];
 for(let i=0;i+1<seg.length;i+=2){if(seg[i])exs.push([seg[i],seg[i+1]||''])}
 return {pos:r[0]||'',form:r[1]||'',zh:r[2]||'',cols:cols,exs:exs,scene:r[5]||''};
}
function v9SceneOf(cardName){return V9_SCENE[String(cardName||'')]||null}
function v9ChunksOf(cardName){return V9_CHUNKS[String(cardName||'')]||null}
function v9ThinkOf(cardName){return V9_THINK[String(cardName||'')]||null}

