/* —— 解析框渲染：场景代入对话 + 词块框架 + 思维任务 —— */
function v9EscA(s){return String(s==null?'':s).replace(/'/g,"\\'").replace(/"/g,'&quot;')}
function v9HlLine(es,k){
 const s=String(es||'');
 if(!k)return esc(s);
 const i=s.toLowerCase().indexOf(String(k).toLowerCase());
 if(i<0)return esc(s);
 return esc(s.slice(0,i))+'<b style="color:var(--sun)">'+esc(s.slice(i,i+String(k).length))+'</b>'+esc(s.slice(i+String(k).length));
}
function v9SceneBlock(q){
 const sc=String((q&&q.scene)||'');
 if(!sc)return '';
 const d=v9SceneOf(sc);
 if(!d)return '';
 let h='<div class="egg-scene">';
 h+='<div class="es-h">🎬 场景代入 · '+esc(d.s||sc)+'</div>';
 const grp=(o,cls)=>{
  if(!o||!o.lines||!o.lines.length)return '';
  let x='<div class="es-grp '+cls+'"><div class="es-who">'+esc(o.who||'')+'</div>';
  o.lines.forEach(l=>{
   x+='<div class="es-line"><button class="es-play" onclick="speak(\''+v9EscA(l[0])+'\')">🔊</button>'
     +'<span class="es-es">'+v9HlLine(l[0],d.k)+'</span>'
     +'<span class="es-zh">'+esc(l[1]||'')+'</span></div>';
  });
  return x+'</div>';
 };
 h+=grp(d.f,'f')+grp(d.c,'c');
 const ck=v9ChunksOf(sc);
 if(ck&&ck.length){
  h+='<div class="es-chunk-h">🧩 词块框架（点读跟读；带 [ ] 的把括号内容换成你的）</div>';
  ck.forEach(c=>{
   const raw=String(c.f||'');
   const hasSlot=/\[[^\]]+\]/.test(raw);
   const f=raw.replace(/\[([^\]]+)\]/g,'<b class="es-slot">[$1]</b>');
   const ex=(c.ex&&c.ex[0])||'';
   h+='<div class="es-chunk"><div class="es-cf">'+f+'</div>'
     +'<div class="es-cz">'+esc(c.zh||'')+(c.t&&c.t!=='—'?' · 可替换：'+esc(c.t):'')+(hasSlot?'':' · 整句跟读')+'</div>'
     +'<div class="es-cx"><button class="es-play" onclick="speak(\''+v9EscA(ex)+'\')">🔊</button> '+esc(ex)
     +' <span class="es-zh">'+esc((c.ex&&c.ex[1])||'')+'</span></div></div>';
  });
 }
 const th=v9ThinkOf(sc);
 if(th){
  h+='<details class="es-think"><summary>🧠 思维训练 · '+esc(th.s||'')+'（点开看三步参考）</summary><div class="es-th-b">';
  (th.st||[]).forEach((s,i)=>{
   h+='<div class="es-step"><span class="es-n">'+(i+1)+'</span><div><b>'+esc(s[0])+'</b>'
     +'<div class="es-ref"><button class="es-play" onclick="speak(\''+v9EscA(s[1])+'\')">🔊</button> '+esc(s[1])+'</div>'
     +'<div class="es-zh">'+esc(s[2]||'')+'</div></div></div>';
  });
  if(th.p&&th.p.length)h+='<div class="es-points">✅ 自检：'+th.p.map(esc).join(' · ')+'</div>';
  h+='</div></details>';
 }
 return h+'</div>';
}

