/* 完整深度词卡：复用 v5Card 的 lx-* 卡片结构（同一模板，仅内容来自 V9_AYUDA） */
function v9AyudaCard(key){
 const A=V9_AYUDA[key];if(!A)return '';
 const S=s=>String(s==null?'':s).replace(/'/g,"\\'").replace(/"/g,'&quot;');
 let h='<div class="lx-head"><span class="lx-w">'+esc(A.word)+'</span><span class="lx-pos">'+esc(A.pos)+'</span><span class="v5-cefr">'+esc(A.cefr||'')+'</span><button onclick="v3CloseLex()">✕</button></div><div class="lx-body">';
 h+='<div class="lx-zh">'+esc(A.zh)+'</div>';
 if(A.ex&&A.ex.length)h+='<div class="lx-sec"><h5>🎬 例句</h5><div class="lx-ex"><button onclick="speak('+JSON.stringify(A.ex[0]).replace(/"/g,'&quot;')+')">🔊</button><span>'+esc(A.ex[0])+(A.ex[1]?'<br><span class="lx-ezh">'+esc(A.ex[1])+'</span>':'')+'</span></div></div>';
 if(A.senses&&A.senses.length)h+='<div class="lx-sec"><h5>📚 多义与分水岭</h5>'+A.senses.map(s=>'<p>'+esc(s)+'</p>').join('')+'</div>';
 if(A.syn||A.ant){h+='<div class="lx-sec"><h5>🔁 同义 · 反义 / 相对</h5>';
  if(A.syn)h+='<p><b style="color:#7FA7C9">同义：</b>'+A.syn.map(s=>esc(s)).join('　')+'</p>';
  if(A.ant)h+='<p><b style="color:#C9A87C">反义/相对：</b>'+A.ant.map(s=>esc(s)).join('　')+'</p>';h+='</div>';}
 if(A.chunks&&A.chunks.length)h+='<div class="lx-sec"><h5>🧩 词块（A1–C1 阶梯搭配）</h5><p>'+A.chunks.map(c=>esc(c)).join('<br>')+'</p></div>';
 if(A.patterns&&A.patterns.length)h+='<div class="lx-sec"><h5>📐 句型结构</h5><p>'+A.patterns.map(p=>esc(p)).join('<br>')+'</p></div>';
 if(A.dialog&&A.dialog.length){h+='<div class="lx-sec"><h5>💬 场景对话</h5>';
  A.dialog.forEach((d,i)=>{const who=i%2===0?'♂':'♀',col=i%2===0?'#409CFF':'#D8A1B1';
   h+='<div class="lx-ex"><button onclick="speak(\''+S(d[0])+'\')">🔊</button><span><b style="color:'+col+'">'+who+' '+esc(d[0])+'</b><br><span class="lx-ezh">'+esc(d[1])+'</span></span></div>';});h+='</div>';}
 if(A.make)h+='<div class="lx-sec" style="border-style:dashed"><h5>✍️ 自己造句</h5><p>'+esc(A.make.task)+'<br><span style="color:#BDB0A0">模板：'+esc(A.make.tmpl)+'</span><br><span style="color:#409CFF">参考：'+esc(A.make.ref)+'</span></p></div>';
 h+='<div class="lx-sec" style="text-align:center"><button onclick="speak(\''+S(A.word)+'\')" style="width:auto;padding:6px 18px;font-weight:900">🔊 听发音</button> '
  +'<button onclick="v3xSave(\''+S(A.save||A.word)+'\')" style="width:auto;padding:6px 14px;font-weight:900;background:#0A84FF;color:#FFFFFF">➕ 收进我的词库</button></div>';
 return h+'</div>';
}
/* 一词一练内联：把同一系统链路压缩进解析卡的「一词一练」区块（不另开模板） */
function v9AyudaInline(word){
 const key=String(word||'').toLowerCase().trim().replace(/^(el|la|los|las|un|una)\s+/,'');
 const A=V9_AYUDA[key];if(!A)return '';
 let h='<div style="margin-top:7px;border-top:1px dashed var(--border);padding-top:6px">';
 h+='<div style="font-size:12px;font-weight:900;color:var(--grape)">🧠 思维导图 · 系统链路（'+esc(A.cefr||'')+'）</div>';
 if(A.chunks&&A.chunks.length)h+='<div style="font-size:11.5px;margin-top:3px;line-height:1.6"><b style="color:var(--sky-d)">词块：</b>'+A.chunks.map(c=>esc(c)).join('　')+'</div>';
 if(A.patterns&&A.patterns.length)h+='<div style="font-size:11.5px;margin-top:2px;line-height:1.6"><b style="color:var(--sky-d)">句型：</b>'+A.patterns.map(p=>esc(p)).join('　')+'</div>';
 if(A.dialog&&A.dialog.length)h+='<div style="font-size:11.5px;margin-top:2px;line-height:1.6"><b style="color:var(--sky-d)">场景对话：</b>'+A.dialog.map(d=>esc(d[0])).join(' ／ ')+'</div>';
 if(A.make)h+='<div style="font-size:11.5px;margin-top:2px;line-height:1.6"><b style="color:var(--sky-d)">自己造句：</b>'+esc(A.make.ref)+'</div>';
 h+='</div>';
 return h;
}
/* 造句闯关：在每日冒险/打卡区内触发，不另设独立板块 */
let V9_CH_POOL=[];
function v9BuildChPool(){if(V9_CH_POOL.length)return;const seen={};CARDS.forEach(c=>(c.v||[]).forEach(v=>{const w=String(v[0]).replace(/^(el|la|los|las)\s+/i,'').toLowerCase();if(w.length>=3&&!seen[w]){seen[w]=1;if(v9ExFor(v[0],1).length)V9_CH_POOL.push(v[0]);}}));}
let V9_CH_IDX=0;
function startSentenceChallenge(){
 v9BuildChPool();if(!V9_CH_POOL.length)return;
 let ov=document.getElementById('v9ch');if(!ov){ov=document.createElement('div');ov.id='v9ch';ov.style.cssText='position:fixed;inset:0;z-index:21000;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,0.55)';document.body.appendChild(ov);}
 let mask=document.getElementById('v9chMask');if(!mask){mask=document.createElement('div');mask.id='v9chMask';mask.style.cssText='position:fixed;inset:0;z-index:20999';mask.onclick=v9CloseChallenge;document.body.appendChild(mask);}
 V9_CH_IDX=Math.floor(Math.random()*V9_CH_POOL.length);v9ChallengeRender();ov.style.display='flex';mask.style.display='block';
}
function v9CloseChallenge(){const ov=document.getElementById('v9ch');const m=document.getElementById('v9chMask');if(ov)ov.style.display='none';if(m)m.style.display='none';}
function v9ChallengeRender(){
 const pool=V9_CH_POOL;if(!pool.length)return;const w=pool[V9_CH_IDX%pool.length];
 const ph=v9PhraseOf(w);
 const target=ph||w;
 const bare=target.replace(/^(el|la|los|las|un|una)\s+/i,'');const d=v5Entry(bare||target);const base=(d.base&&d.base.indexOf(' ')<0)?d.base:(bare.split(/\s+/)[0]||bare);
 const S=s=>String(s==null?'':s).replace(/'/g,"\\'").replace(/"/g,'&quot;');
 let ex=v9ExFor(target,2);if(!ex.length)ex=[v9Sent(w,d.pos)];
 const st=ph?v9PhraseStruct(ph):v5Structure(d);const dr=v3xDrill(target,{0:d.pos,1:d.zh});
 let h='<div style="max-width:380px;width:90%;background:var(--card,#1C1C1E);border-radius:18px;padding:18px 18px 14px;box-shadow:0 18px 50px rgba(0,0,0,0.5)">';
 h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><b style="font-size:15px">✍️ 造句闯关</b><button onclick="v9CloseChallenge()" style="border:0;background:transparent;color:var(--muted);font-size:18px;cursor:pointer">✕</button></div>';
 h+='<div style="font-size:18px;font-weight:900;margin:6px 0">'+esc(w)+' <span style="color:var(--sky-d);font-size:13px">'+esc(d.pos)+'</span> <span style="color:var(--muted);font-size:13px">'+esc(d.zh||'')+'</span></div>';
 h+='<div style="font-size:12px;color:var(--muted)">🎬 先看两句真实例句（点读）</div>';
 ex.forEach(x=>{h+='<div style="margin:4px 0"><button onclick="speak(\''+S(x[0])+'\')" style="border:0;background:var(--v-primary);color:var(--v-ink);border-radius:6px;padding:2px 8px;font-size:11px;cursor:pointer">🔊</button> <span style="font-size:13px">'+esc(x[0])+' <span style="color:var(--muted)">'+esc(x[1]||'')+'</span></span></div>';});
 h+='<div style="font-size:13px;color:var(--grape);margin-top:6px"><b>🧩 句型结构：</b>'+esc(st)+'</div>';
 h+='<div style="font-size:13px;margin-top:6px"><b>✍️ 你的任务：</b>'+esc(dr[0])+'<br><span style="color:var(--muted);font-size:12px">模板：'+esc(dr[1])+'</span></div>';
 h+='<div id="v9chRef" style="display:none;font-size:13px;color:var(--mint);margin-top:6px"><b>参考：</b>'+esc(dr[2])+'</div>';
 h+='<div style="margin-top:10px;display:flex;gap:8px">'
   +'<button onclick="document.getElementById(\'v9chRef\').style.display=\'block\'" style="flex:1;border:0;background:var(--mint);color:var(--v-lock-soft);border-radius:10px;padding:9px;font-weight:900;cursor:pointer">看参考句</button>'
   +'<button onclick="V9_CH_IDX++;v9ChallengeRender()" style="flex:1;border:0;background:var(--sky-d);color:var(--v-ink);border-radius:10px;padding:9px;font-weight:900;cursor:pointer">换一个 ➡️</button>'
   +'</div>';
 h+='<div style="font-size:11px;color:var(--faint);margin-top:8px;text-align:center">第 '+String((V9_CH_IDX%pool.length)+1)+' / '+pool.length+' 词 · 用这个词造一句旅行相关的话，再对照参考</div>';
 h+='</div>';
 const ov=document.getElementById('v9ch');if(ov)ov.innerHTML=h;
}
/* —— 全站解析卡统一入口（锚点）——
   收敛说明：v3x（第 3 代词库）与 v5（第 5 代增强卡）曾各自覆盖 window.v3ShowLex，
   最后一次覆盖者胜出，导致「点词解析」实际行为取决于脚本加载顺序，且 v3x 的
   未收录词兜底逻辑被静默丢弃。现改为唯一实现：优先增强卡 v5Card，失败再回落 v3xCard。
   @anchor:showLex */
function showLex(word){
 let ov=document.getElementById('v3lex');
 if(!ov){ov=document.createElement('div');ov.id='v3lex';document.body.appendChild(ov);}
 let html='';
 try{ if(typeof v5Card==='function')html=v5Card(word); }catch(e){ html=''; }
 if(!html){ try{ html=v3xCard(word); }catch(e2){ html=''; } }
 if(!html)return;
 ov.innerHTML=html;
 ov.classList.add('show');ov.style.zIndex='20000';
 const m=document.getElementById('v3lexMask');if(m)m.classList.add('show');
}
window.v3ShowLex=showLex;
/* —— 语法句型库（统一原首页速记口诀 + 时态/重音/从句/前置词 + 动词变位）—— */
const V5_GRAMMAR_LIB=[
 {k:'变位',t:'-ar 动词现在时',l:['我 o 你 as 他 a，我们 amos 你们 áis 他们 an','口诀：yo -o · tú -as · él -a · nosotros -amos · vosotros -áis · ellos -an','例：hablo / hablas / habla / hablamos / habláis / hablan']},
 {k:'变位',t:'-er / -ir 动词现在时',l:['-er 我们 emos，-ir 我们 imos，其余相同','例：como / comes / come / comemos / coméis / comen','例：vivo / vives / vive / vivimos / vivís / viven']},
 {k:'时态',t:'将来时（简单将来）',l:['原形后直接加 é / ás / á / emos / éis / án','Viajaré mañana.（我明天出发）','不规则：tener→tendré · poder→podré · decir→diré']},
 {k:'时态',t:'简单过去时（pretérito perfecto simple）',l:['-ar：é / aste / ó / amos / asteis / aron','-er/-ir：í / iste / ió / imos / isteis / ieron','线索词：ayer · anoche · el año pasado · la semana pasada']},
 {k:'时态',t:'过去未完成时（imperfecto）',l:['-ar：aba / abas / aba / ábamos / aban','-er/-ir：ía / ías / ía / íamos / ían','用途：描述背景、习惯、童年，常与简单过去配合'],
  },
 {k:'时态',t:'现在完成时',l:['haber（he/has/ha/hemos/han）+ 过去分词','线索词：ya · hoy · esta mañana · alguna vez','Yo he visitado Sevilla.（我去过塞维利亚）']},
 {k:'重音',t:'西语重音三法则',l:['aguda（倒数一重读）：以元音/n/s 结尾带重音符号 → hablé','grave（倒数二重读）：不以元音/n/s 结尾带重音符号 → difícil','esdrújula（倒数三重读）：永远带重音符号 → esdrújula','h 永远不发音；ñ 是独立字母']},
 {k:'句式',t:'ser vs estar（最经典的一次分家）',l:['ser = 本质身份：soy de China / es médico','estar = 状态位置：estoy cansado / está cerrado','口诀：本质 ser，状态 estar；地点也归 estar']},
 {k:'句式',t:'gustar 类倒装动词',l:['Me gusta el libro.（书讨我喜欢）','Me gustan las playas.（复数主语 → gustan）','同类：encantar · interesar · importar · molestar']},
 {k:'句式',t:'por vs para（目的原因一线分）',l:['por：原因、经过、期间、被动施动者（por la mañana）','para：目的、对象、期限、用途（para viajar）','口诀：para 向前看目的，por 回头看原因']},
 {k:'从句',t:'名词从句 / 定语从句',l:['肯定陈述 + 否定虚拟：Creo que viene / No creo que venga','定语从句：人 quien · 物 que · 地点 donde · 时间 cuando']},
 {k:'从句',t:'副词从句与 si 条件',l:['porque 因为 · para que 以便 · aunque 虽然 · cuando 当','si + 现在时 → 将来时：Si tengo tiempo, iré','si + 过去虚拟 → 条件式：Si tuviera tiempo, iría']},
 {k:'前置词',t:'动词必带前置词（本土搭配）',l:['soñar con（梦见）· casarse con（与…结婚）','pensar en（想着）· interesarse en（对…有兴趣）','depender de（取决于）· estar harto de（受够了）','ir a（去）· empezar a（开始）· volver a（重新）']},
 {k:'命令',t:'命令式速成',l:['tú 肯定：habla / come / vive（第三人称单数形式）','usted 正式：hable / coma / viva','vosotros：hablad / comed / vivid','否定祈使用虚拟式：No hables así']},
 {k:'虚拟',t:'ojalá 与虚拟式',l:['ojalá + 虚拟式表愿望：ojalá tengas buen viaje','dudo que / no creo que + 虚拟式','es importante que + 虚拟式']},
 {k:'名词',t:'名词性别系统',l:[
  '名词性别以词典为准，不能只凭词尾判断：el problema（阳）、el mapa（阳）、la mano（阴）、la foto（阴）',
  '-ción/-sión/-dad/-tad/-tud/-umbre 结尾多为阴性：la acción、la libertad、la educación',
  '-ma 多为阳性（el problema / el sistema / el tema）；-ta 多为阴性（la cita / la visita / la receta），须逐词确认',
  '-ista/-nte 多为通性：el/la finalista、el/la estudiante',
  '以重读 a-/ha- 开头的阴性名词，单数用 el/un（el agua / un aula），形容词仍用阴性（el agua fría）',
  '形容词须与名词性数一致；部分形容词阴阳同形：importante、interesante、fácil、azul',
  '记忆方法：记名词时连同冠词一起记']},
 {k:'时态',t:'时间线索与时态选择（提示≠决定）',l:[
  '时间词只提示可能性，不能一词对应一时态；判断依据是「事件是否完成、是否持续、与说话时间的关系」',
  'ayer / anoche / el año pasado：常见于简单过去时 — Ayer fui al cine.',
  'todos los días / siempre：现在的习惯常用现在时 — Todos los días estudio español.（也可叙述过去习惯）',
  'mañana / la semana que viene：将来表达 — Mañana estudiaré. / Voy a estudiar. / Mañana tengo reunión.（安排）',
  'ya / hoy：依语境 — Hoy he estudiado mucho.（今天到现在）/ Hoy estudio.（今天 habitualmente）',
  'antes / de pequeño / mientras：过去习惯或背景 — De pequeño jugaba al fútbol.',
  'si + 过去虚拟式：非现实条件 — Si tuviera tiempo, viajaría más.',
  'ojalá + 虚拟式：愿望，时态随现实距离变化 — Ojalá tenga tiempo. / Ojalá tuviera tiempo.',
  '⚠ 地区差异：西班牙口语中现在完成时覆盖「今天」的时间段，拉美多倾向用简单过去时；不要以单一地区为准'
 ]}
];
/* —— 词汇中心（统一：查词 / 我的生词本 / 语法句型库 / 思维导图）—— */
let V5_TAB='word';
function v5OpenVocab(tab){V5_TAB=tab||'word';v5RenderVocab('')}
function v5RenderVocab(q){
 let ov=document.getElementById('v3xdict');
 if(!ov){ov=document.createElement('div');ov.id='v3xdict';ov.className='v3x-bank';document.body.appendChild(ov);}
 q=(q||'').trim();
 let h='<div class="v3xb-top"><b>📖 词汇中心 · Vocabulario</b><span>'+Object.keys(V3X_DATA.words).length+' 词 · '+Object.keys(V3_LEX).length+' 条手工词条 · 题库例句联动</span><button onclick="v3CloseDict()">✕</button></div>';
 h+='<div class="v5-tabs">'
  +'<button class="'+(V5_TAB==='word'?'on':'')+'" onclick="v5OpenVocab(\'word\')">🔍 查词</button>'
  +'<button class="'+(V5_TAB==='saved'?'on':'')+'" onclick="v5OpenVocab(\'saved\')">⭐ 我的生词本 '+V3X_SAVED.length+'</button>'
  +'<button class="'+(V5_TAB==='grammar'?'on':'')+'" onclick="v5OpenVocab(\'grammar\')">📐 语法句型库</button>'
  +'<button class="'+(V5_TAB==='root'?'on':'')+'" onclick="v5OpenVocab(\'root\')">🌱 拉丁词根</button>'
  +'</div>';
 if(V5_TAB==='word')h+=v5TabWord(q);
 else if(V5_TAB==='saved')h+=v5TabSaved();
 else if(V5_TAB==='grammar')h+=v5TabGrammar();
 else h+=v5TabRoot();
 ov.innerHTML=h;
 ov.classList.add('show');
 v3xdAttachLazy(ov);
}
function v5TabWord(q){
 const words=V3X_WORDS;
 let list=words;
 if(q){
  const nq=v3Norm(q);
  list=words.filter(w=>{const e=V3X_DATA.words[w];return v3Norm(w).includes(nq)||w.toLowerCase().includes(q.toLowerCase())||(e&&e[1].includes(q))}).slice(0,150);
 }
 let h='<div class="v3xd-search"><input id="v5wdInput" placeholder="输入西语或中文（支持变位：tengo → tener）" value="'+q.replace(/"/g,'&quot;')+'" oninput="v5Search(this.value)"><button onclick="v3xdSpeak(0,\'v5wdInput\')">🔊</button></div>';
 h+='<div class="v3xd-note">'+(q?('「'+q+'」→ '+list.length+' 条'):'点击词条 = 多义 + 词根词缀 + 语法用法 + 高频句型 + 题库例句 + 男女对话')+'</div>';
 const groups={};
 list.forEach(w=>{const L=(w[0]||'#').toUpperCase();const k=/[A-ZÁÉÍÓÚÑ]/.test(L)?L:'#';(groups[k]=groups[k]||[]).push(w)});
 const letters=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'es'));
 h+='<div class="v3xd-az">'+letters.map(L=>'<a href="javascript:void(0)" onclick="v3xJump(\''+L+'\')">'+L+'</a>').join('')+'</div>';
 /* 性能修复：5175 词全量一次渲染会严重卡顿 → 先渲染字母组占位，滚动临近时再填充（v3xdAttachLazy）*/
 window.__v3xdPending=groups;
 letters.forEach(L=>{
  h+='<div class="v3xd-group" id="v3xdG-'+L+'" data-g="'+L+'"><div class="v3xd-letter">'+L+'</div><div class="v3xd-words" style="min-height:'+Math.min(groups[L].length,600)*62+'px"></div></div>';
 });
 return h;
}
/* —— A-Z 词表懒加载共享工具（词汇中心 / 生词查询引擎共用）—— */
function v3xdItemHTML(w){
 const e=V3X_DATA.words[w];const saved=V3X_SAVED.indexOf(w)>=0;
 return '<div class="v3xd-item'+(saved?' saved':'')+'" onclick="v3ShowLex(\''+w.replace(/'/g,"\\'")+'\')"><b>'+w+'</b><span>'+e[0]+' · '+e[1]+'</span>'+(saved?'<i>⭐</i>':'')+'</div>';
}
function v3xdFillGroup(L){
 const g=(window.__v3xdPending||{})[L];const el=document.getElementById('v3xdG-'+L);
 if(!g||!el||el.dataset.done)return; el.dataset.done='1';
 const box=el.querySelector('.v3xd-words');if(box)box.innerHTML=g.map(v3xdItemHTML).join('');
}
function v3xdAttachLazy(ov){
 if(!ov)return;
 if(ov.__lazyIO){try{ov.__lazyIO.disconnect()}catch(e){}}
 if(!('IntersectionObserver' in window)){Object.keys(window.__v3xdPending||{}).forEach(v3xdFillGroup);return;}
 const io=new IntersectionObserver(es=>{es.forEach(en=>{if(en.isIntersecting){v3xdFillGroup(en.target.dataset.g);io.unobserve(en.target);}})},{root:ov,rootMargin:'900px 0px'});
 ov.querySelectorAll('.v3xd-group[data-g]').forEach(g=>io.observe(g));
 ov.__lazyIO=io;
}
function v5TabSaved(){
 if(!V3X_SAVED.length)return '<div class="v3xd-note">还没有收藏。在任意解析卡点「➕ 收进我的词库」即可沉淀到这里。</div>';
 let h='<div class="v3xd-note">我的生词本 '+V3X_SAVED.length+' 词 · 可点开复习或移除</div><div class="v3xb-my">';
 V3X_SAVED.forEach(w=>{h+='<span class="v3xb-w" onclick="v3ShowLex(\''+w.replace(/'/g,"\\'")+'\')">'+w+' <b onclick="event.stopPropagation();v3xSave(\''+w.replace(/'/g,"\\'")+'\');v5OpenVocab(\'saved\')">✕</b></span>'});
 return h+'</div>';
}
function v5TabGrammar(){
 let h='<div class="v3xd-note">全站统一语法句型库：15 张卡覆盖变位 / 时态 / 重音 / 句式 / 从句 / 虚拟 / 命令 / 前置词</div><div class="v5-glib">';
 V5_GRAMMAR_LIB.forEach((g,i)=>{
  h+='<div class="v5-gcard"><div class="v5-ghead"><span class="v5-gk2">'+g.k+'</span><b>'+g.t+'</b></div>'
   +g.l.map(l=>'<div class="v5-gline2">· '+l+'</div>').join('')
   +'<button onclick="speak(\''+g.t.split('（')[0].replace(/'/g,"\\'")+'\')">🔊 读标题</button></div>';
 });
 return h+'</div>';
}
function v5TabRoot(){
 let h='<div class="v3xd-note">拉丁词根 '+V3X_DATA.roots.length+' 族 · 点任一词根看同族词</div>';
 V3X_DATA.roots.forEach((r,i)=>{
  const fam=V3X_WORDS.filter(w=>{const e=V3X_DATA.words[w];return e&&e[2]===i}).slice(0,14);
  if(!fam.length)return;
  h+='<div class="v5-root-row"><div class="v5-root-h"><span class="v5-root-tag">'+r[0]+'</span><span class="v5-root-mn">'+r[2]+'</span><span class="v5-root-src">'+r[1]+'</span></div><div class="v5-root-fam">'
   +fam.map(w=>'<span onclick="v3ShowLex(\''+w.replace(/'/g,"\\'")+'\')">'+w+'</span>').join('')+'</div></div>';
 });
 return h;
}
let v5Timer=null;
function v5Search(v){clearTimeout(v5Timer);v5Timer=setTimeout(()=>v5RenderVocab(v),200)}
