/* —— 全题库注解/高亮接入变位还原（原 V3_IDX 只认原形，覆盖偏低）—— */
(function(){
 const key=w=>{
  const k=V3_IDX[v3Norm(w)];if(k)return k;
  const L=v5Lemma(w);if(L)return L;
  return null;
 };
 const orig=window.v3AnnotateHTML;
 const mine=function(html){
  return String(html).replace(/>([^<]+)</g,(m,txt)=>{
   const nt=txt.replace(/[A-Za-zÁÉÍÓÚÑáéíóúüñ]+/g,w=>{
    const hit=key(w);
    return hit?`<span class="v3w" data-w="${hit}">${w}</span>`:w;
   });
   return '>'+nt+'<';
  });
 };
 window.v3AnnotateHTML=function(html){try{return mine(html)}catch(e){return orig?orig.apply(this,arguments):html}};
 // 题目导读条的注解 chips 也用还原后的原形
 if(typeof window.v3xAnnotateQuestion==='function'){
  const oq=window.v3xAnnotateQuestion;
  window.v3xAnnotateQuestion=function(q){
   const es=v3xExtractEs(q)||'';
   const seen={},hits=[];
   (String(es).replace(/<[^>]*>/g,' ').match(/[A-Za-zÁÉÍÓÚÑáéíóúüñ]+/g)||[]).forEach(raw=>{
    if(hits.length>=8)return;
    const k=key(raw);if(!k||seen[k])return;seen[k]=1;
    const e=V3X_DATA.words[k]||V3_LEX[k]||null;
    const zh=e?(e[1]||e.zh||''):'';
    if(zh)hits.push({w:k,zh:zh});
   });
   const kindName=(TYPE_INFO[q.kind]&&TYPE_INFO[q.kind].name)||q.kind;
   const scene=(q.scene||(THEMES[q.theme-1]&&THEMES[q.theme-1].name))||'旅行场景';
   const guide=V3X_KIND_GUIDE[q.kind]||'先读题干，再作答；点注解词看解析。';
   const chipHtml=hits.length?hits.map(h=>`<span class="v3xa-chip" onclick="event.stopPropagation();v3ShowLex('${h.w.replace(/'/g,"\\'")}')">${h.w}<i>${h.zh}</i></span>`).join(''):'<span class="v3xa-none">题干为常用句式，逐词见下方解析卡与全文点词。</span>';
   return `<div class="v3xa-bar" onclick="event.stopPropagation()"><div class="v3xa-guide">📖 <b>导读</b>｜${scene} · ${kindName}：${guide}</div><div class="v3xa-chips"><b>🔍 生词注解</b>${chipHtml}</div></div>`;
  };
 }
})();

