 window.v6Neutralize=function(){
  const BLUE=/#(2b6cb0|0c8599|74a3b8|5c7f92|d9e6ff|4a357a|7048e8|6d28d9|7c3aed|8b5cf6|9775fa|a78bfa|b197fc|c4b5fd|6d4bd6)/i;
  document.querySelectorAll('[style]').forEach(el=>{
   const st=el.getAttribute('style')||'';
   if(!BLUE.test(st))return;
   el.setAttribute('style',st.replace(/#1E4B7B/ig,'#409CFF').replace(/#177382/ig,'#409CFF')
    .replace(/#345665/ig,'#645035').replace(/#3B525E/ig,'#409CFF').replace(/#1A1A1A/ig,'#1A1A1A')
    .replace(/#412E6B/ig,'#2A2A2A').replace(/#321782/ig,'#409CFF').replace(/#411782/ig,'#663933')
    .replace(/#3E1782/ig,'#409CFF').replace(/#381782/ig,'#6C462D').replace(/#321782/ig,'#409CFF')
    .replace(/#321782/ig,'#754D24').replace(/#331782/ig,'#714E28').replace(/#2D1782/ig,'#715228')
    .replace(/#341C7D/ig,'#704729'));
  });
 };
