 window.v8ClueTip=function(w){
  const t=document.getElementById('v8cluetip');
  const def=window.V8_CLUES[w]||w;
  t.innerHTML='<b>'+w+'</b><br>'+def+'<div style="text-align:right;margin-top:6px"><span style="opacity:.7;font-size:11px;cursor:pointer" onclick="document.getElementById(\'v8cluetip\').style.display=\'none\'">关闭 ✕</span></div>';
  t.style.display='block';
  clearTimeout(window.__v8ct);window.__v8ct=setTimeout(function(){t.style.display='none'},6000);
 };
 function clueChips(es){
  const out=[];
  Object.keys(window.V8_CLUES).forEach(function(w){
   const re=new RegExp('(^|[^A-Za-zÁÉÍÓÚÑáéíóúñ])'+w.replace(/ /g,'\\s')+'(?![A-Za-zÁÉÍÓÚÑáéíóúñ])','i');
   if(re.test(es)&&out.length<4)out.push(w);
  });
  return out;
 }
