/* —— 阅读篇：逐句中西对照 + 线索词 chips —— */
 window.v4Read=function(){
  const arts=QUESTIONS.filter(function(x){return x.kind==='gapfill'&&x.article});
  const q=arts[window.V8_CURART]||arts[0];
  if(!q)return '<div class="v4-art-head"><h2>暂无阅读篇素材</h2></div>';
  const g=v4Gram(8);
  const zh=window.V8_READZH[window.V8_CURART]||[];
  let tabs='<div class="v8-art-tabs">'+arts.map(function(a,i){
   return '<div class="v8-art-tab'+(i===window.V8_CURART?' on':'')+'" onclick="V8_CURART='+i+';v4RenderMag()">'+(a.scene||('阅读 '+(i+1)))+'</div>';
  }).join('')+'</div>';
  const sents=q.article.split(/\[\d+\]/).map(function(x){return x.replace(/^\s+|\s+$/g,'')}).filter(Boolean);
  let rows='';
  sents.forEach(function(es,i){
   const blanks=(es.match(/\[\d+\]/g)||[]).length;
   const clues=clueChips(es);
   rows+='<div class="v8-sent"><span class="n">'+(i+1)+'</span>'
    +'<div class="es" onclick="speak(this.dataset.t)" data-t="'+esc(es).replace(/"/g,'&quot;')+'">'+v4Slot(v4Hl(esc(es)))+' 🔊</div>'
    +'<div class="zh">🇨🇳 '+(zh[i]||'（释义整理中）')+'</div>'
    +(clues.length?'<div class="clues">'+clues.map(function(w){return '<span class="v8-clue" onclick="v8ClueTip(\''+w+'\')">🔎 '+w+'</span>'}).join('')+'</div>':'')
    +'</div>';
  });
  return '<div class="v4-art-head"><span class="v4-art-no">03</span><h2>✍️ 阅读篇模板 · Lectura Bilingüe</h2><p>逐句中西对照精读：点西语句听发音，点高亮词看词汇解析，点线索词看语法解析——每句都有中文释义。</p>'
   +'<div class="v4-playrow"><button onclick="speak('+JSON.stringify(q.article).replace(/"/g,'&quot;')+')">🔊 全文连播</button><button onclick="v4DoQuiz(\''+q.id+'\')">📝 去做这篇练习</button></div></div>'
   +tabs+rows
   +'<details class="v6-fold"><summary><span class="v6-tag">EXT_GRAMMAR</span>📐 本篇语法线索词 · 中文解析<span style="margin-left:auto;color:#409CFF">展开 ▾</span></summary><div class="v6-fold-b">'
   +'<div class="v4-gline"><span class="v4-gk">时态信号</span>ayer/anoche→简单过去时（已完成）；siempre/cada día→过去未完成（习惯）；ya→完成时；mañana→将来</div>'
   +'<div class="v4-gline"><span class="v4-gk">从句线索</span>cuando 当…时 / si 如果 / porque 因为 / como 由于 / para que 为了 / mientras 与此同时</div>'
   +'<div class="v4-gline"><span class="v4-gk">逻辑连接</span>primero 首先 / entonces 于是 / después 之后 / al final 最后 / pero 但是 / por eso 因此</div>'
   +'<div class="v4-gline"><span class="v4-gk">特殊结构</span>al+原形=一…就；se+动词=自复被动（早餐被供应）；le=与格（给他/她）</div>'
   +'</div></details>';
 };
