/* ===== v8.3 站点折叠 + 页面清洁 ===== */
(function(){
 function v83Fold(){
  const wrap=document.querySelector('#themeGrid .stage-wrap');if(!wrap)return;
  const kids=Array.prototype.slice.call(wrap.children);
  let cur=null;
  kids.forEach(function(el){
   const isHead=el.classList&&el.classList.contains('stage-head');
   if(isHead){
    const isStage=/第[0-4四]站|入门站|出发站|在途站|深入站|融入站/.test(el.textContent);
    if(isStage){
     cur=el;
     if(!el.classList.contains('v83-fold')){
      el.classList.add('v83-fold');
      const ar=document.createElement('span');ar.className='v83-arrow';ar.textContent='▸';
      el.appendChild(ar);
      el.addEventListener('click',function(){
       const open=el.dataset.open==='1';
       const nowOpen=!open;
       el.dataset.open=nowOpen?'1':'0';
       ar.textContent=nowOpen?'▾':'▸';
       el.parentElement.querySelectorAll('[data-v83g="'+el.dataset.v83id+'"]').forEach(function(n){
        n.style.display=open?'none':'';
       });
      });
      el.dataset.v83id='g'+Array.prototype.indexOf.call(kids,el);
      el.dataset.open='0';
     }
    }else{cur=null;}
    return;
   }
   if(cur){el.setAttribute('data-v83g',cur.dataset.v83id||'');el.style.display='none';}
  });
 }
 /* 挂钩最新渲染链（含 v61 重排） */
 const ost=window.v3RenderStages;
 if(typeof ost==='function'){
  window.v3RenderStages=function(){const r=ost.apply(this,arguments);try{v83Fold()}catch(e){}return r;};
 }else{
  document.addEventListener('DOMContentLoaded',function(){try{v83Fold()}catch(e){}});
 }
})();